class Solution {
public:
    int numWays(string s) {
        const int MOD = 1000000007;
        int n = s.size();
        int total = 0;
        for (char c : s) if (c == '1') total++;
        if (total % 3 != 0) return 0;
        int k = total / 3;
        if (k == 0) {
            long long gaps = n - 1;
            long long ans = gaps * (gaps - 1) / 2 % MOD;
            return (int)ans;
        }
        int count = 0;
        int firstEnd = -1, secondStart = -1, secondEnd = -1, thirdStart = -1;
        for (int i = 0; i < n; i++) {
            if (s[i] == '1') {
                count++;
                if (count == k) firstEnd = i;
                else if (count == k + 1) secondStart = i;
                if (count == 2 * k) secondEnd = i;
                else if (count == 2 * k + 1) thirdStart = i;
            }
        }
        long long ways1 = secondStart - firstEnd;
        long long ways2 = thirdStart - secondEnd;
        long long ans = ways1 * ways2 % MOD;
        return (int)ans;
    }
};
